async function importCodexHistory(options) {
  const cutoff = options.now - WINDOW_MS;
  let cursor = options.cursor;
  let completedBatch = options.completedBatch;
  do {
    const page = await withCodexAppServer({ cwd: options.cwd, spawnProcess: options.spawnProcess, timeoutMs: 3e4 }, async (client) => {
      const listed = await client.request("thread/list", { cursor, limit: 20, sortKey: "updated_at", sortDirection: "desc", sourceKinds: ["cli", "vscode", "appServer"] });
      if (!Array.isArray(listed.data))
        throw new Error("history_list_invalid");
      const threads = [];
      for (const summary of listed.data) {
        const item = summary;
        if (typeof item.id !== "string" || typeof item.updatedAt !== "number" || item.updatedAt * 1e3 <= cutoff)
          continue;
        const read = await client.request("thread/read", { threadId: item.id, includeTurns: true });
        threads.push(...extractTurn(read.thread, cutoff));
      }
      const reachedCutoff = listed.data.some((summary) => {
        const updatedAt = summary?.updatedAt;
        return typeof updatedAt === "number" && updatedAt * 1e3 <= cutoff;
      });
      return { threads, nextCursor: !reachedCutoff && typeof listed.nextCursor === "string" ? listed.nextCursor : null };
    });
    for (const turn of page.threads) {
      const extracted = await runWorker({
        dataDir: options.dataDir,
        spawnProcess: options.spawnProcess,
        prompt: turn.prompt,
        startWorker: options.startWorker,
        workerCancelled: options.workerCancelled
      });
      if (extracted.disposition !== "analyze" || extracted.items.length === 0)
        continue;
      await options.record({
        codex_task_id: turn.taskId,
        turn_id: turn.turnId,
        message_id: "",
        source: "history",
        occurred_at: turn.occurredAt,
        expires_at: turn.occurredAt + WINDOW_MS,
        ...turn.cwd ? { workspace_path: turn.cwd } : {},
        prompt: turn.prompt,
        recommendation_enabled: false,
        observations: extracted.items.map((item) => ({
          relation: item.relation,
          confidence: item.confidence,
          variable_slots: item.variables,
          fingerprint: {
            core_goal: item.core_goal,
            input_roles: item.input_roles,
            output: item.output,
            essential_steps: item.essential_steps,
            scope: item.scope_hint
          }
        }))
      });
    }
    cursor = page.nextCursor;
    completedBatch += 1;
    await options.progress({ cursor, sourceId: page.threads.at(-1)?.taskId ?? null, completedBatch });
  } while (cursor);
}

